package by.freeway.calculator;                                  // Объявляем пакет, в котором находится этот класс

import javafx.fxml.FXML;                                        // Импортируем аннотацию FXML для связывания с элементами из FXML-файла
import javafx.scene.control.TextField;                          // Импортируем класс TextField для работы с полем ввода/вывода
import javafx.scene.control.Button;                             // Импортируем класс Button для работы с кнопками

public class HelloController {                                  // Объявляем публичный класс контроллера
    @FXML                                                       // Аннотация, указывающая, что это поле связано с элементом из FXML-файла (по fx:id="display")
    private TextField display;                                  // Объявляем приватное поле для экрана калькулятора

    private double num1 = 0;                                    // Объявляем переменную для хранения первого числа, инициализируем нулём
    private String operator = "";                               // Объявляем переменную для хранения знака операции, инициализируем пустой строкой
    private boolean start = true;                               // Флаг, указывающий, начинается ли ввод нового числа (true - да, false - продолжение)

    @FXML                                                       // Аннотация для метода, который вызывается при нажатии на кнопку с цифрой из FXML
    public void onNumberClick(javafx.event.ActionEvent event) { // Объявляем публичный метод обработки нажатия цифры
        if (display.getText().equals("Error")) {                // Проверяем, если на экране написано "Error"
            onClear();                                          // Вызываем метод очистки, чтобы сбросить ошибку
        }                                                       // Закрываем блок if
        Button button = (Button) event.getSource();             // Получаем ссылку на кнопку, которая была нажата, из события
        if (start) {                                            // Проверяем, если это начало ввода нового числа
            display.setText(button.getText());                   // Устанавливаем текст экрана равным тексту нажатой кнопки (перезаписываем)
            start = false;                                      // Меняем флаг на false, так как ввод уже начался
        } else {                                                // Иначе, если ввод числа уже продолжается
            display.setText(display.getText() + button.getText()); // Добавляем новую цифру к уже существующему тексту на экране
        }                                                       // Закрываем блок else
    }                                                           // Закрываем метод onNumberClick

    @FXML                                                       // Аннотация для метода, вызываемого при нажатии на кнопку десятичной точки
    public void onDecimalClick() {                              // Объявляем публичный метод обработки нажатия точки
        if (display.getText().equals("Error")) {                // Проверяем, если на экране написано "Error"
            onClear();                                          // Вызываем метод очистки, чтобы сбросить ошибку
        }                                                       // Закрываем блок if
        if (start) {                                            // Проверяем, если это начало ввода нового числа
            display.setText("0.");                              // Устанавливаем текст экрана как "0."
            start = false;                                      // Меняем флаг на false, так как ввод начался
        } else if (!display.getText().contains(".")) {          // Иначе, если текущий текст на экране еще не содержит точку
            display.setText(display.getText() + ".");           // Добавляем точку к текущему тексту на экране
        }                                                       // Закрываем блок else if
    }                                                           // Закрываем метод onDecimalClick

    @FXML                                                       // Аннотация для метода, вызываемого при нажатии на кнопку оператора (+, -, *, /)
    public void onOperatorClick(javafx.event.ActionEvent event) { // Объявляем публичный метод обработки нажатия оператора
        if (display.getText().equals("Error")) {                // Проверяем, если на экране написано "Error"
            return;                                             // Прерываем выполнение метода, ничего не делая
        }                                                       // Закрываем блок if
        Button button = (Button) event.getSource();             // Получаем ссылку на нажатую кнопку из события
        operator = button.getText();                            // Сохраняем текст кнопки (знак операции) в переменную operator
        try {                                                   // Начинаем блок try для безопасного выполнения кода, который может вызвать ошибку
            num1 = Double.parseDouble(display.getText());       // Преобразуем текст с экрана в число double и сохраняем в num1
            start = true;                                       // Устанавливаем флаг start в true, чтобы следующее нажатие цифры начало новое число
        } catch (NumberFormatException e) {                     // Ловим исключение, если преобразование текста в число не удалось
            display.setText("Error");                           // Устанавливаем текст экрана в "Error"
            start = true;                                       // Устанавливаем флаг start в true для подготовки к сбросу
        }                                                       // Закрываем блок catch
    }                                                           // Закрываем метод onOperatorClick

    @FXML                                                       // Аннотация для метода, вызываемого при нажатии на кнопку "="
    public void onEqualClick() {                                // Объявляем публичный метод обработки нажатия кнопки равно
        if (display.getText().equals("Error") || operator.isEmpty()) { // Проверяем, если на экране "Error" или оператор не выбран
            return;                                             // Прерываем выполнение метода
        }                                                       // Закрываем блок if
        double num2;                                            // Объявляем переменную для хранения второго числа
        try {                                                   // Начинаем блок try для безопасного преобразования
            num2 = Double.parseDouble(display.getText());       // Преобразуем текущий текст экрана в число double и сохраняем в num2
        } catch (NumberFormatException e) {                     // Ловим исключение при ошибке преобразования
            display.setText("Error");                           // Устанавливаем текст экрана в "Error"
            start = true;                                       // Устанавливаем флаг start в true для сброса
            return;                                             // Прерываем выполнение метода
        }                                                       // Закрываем блок catch

        double result = 0;                                      // Объявляем переменную для хранения результата вычислений, инициализируем нулём
        switch (operator) {                                     // Начинаем оператор выбора switch по значению переменной operator
            case "+":                                           // Если оператор равен "+"
                result = num1 + num2;                           // Складываем num1 и num2, результат сохраняем в result
                break;                                          // Прерываем выполнение switch, чтобы не проверять другие варианты
            case "-":                                           // Если оператор равен "-"
                result = num1 - num2;                           // Вычитаем num2 из num1, результат сохраняем в result
                break;                                          // Прерываем выполнение switch
            case "*":                                           // Если оператор равен "*"
                result = num1 * num2;                           // Умножаем num1 на num2, результат сохраняем в result
                break;                                          // Прерываем выполнение switch
            case "/":                                           // Если оператор равен "/"
                if (num2 == 0) {                                // Проверяем, если второе число равно нулю (защита от деления на ноль)
                    display.setText("Error");                   // Устанавливаем текст экрана в "Error"
                    start = true;                               // Устанавливаем флаг start в true для сброса
                    return;                                     // Прерываем выполнение метода
                }                                               // Закрываем блок if
                result = num1 / num2;                           // Делим num1 на num2, результат сохраняем в result
                break;                                          // Прерываем выполнение switch
        }                                                       // Закрываем оператор switch

        if (result == (long) result) {                          // Проверяем, является ли результат целым числом (без дробной части)
            display.setText(String.format("%d", (long) result)); // Форматируем и выводим результат как целое число (без .0)
        } else {                                                // Иначе, если число дробное
            display.setText(String.format("%s", result));       // Форматируем и выводим результат как строку с дробной частью
        }                                                       // Закрываем блок else
        start = true;                                           // Устанавливаем флаг start в true, чтобы следующий ввод начал новое число
    }                                                           // Закрываем метод onEqualClick

    @FXML                                                       // Аннотация для метода, вызываемого при нажатии на кнопку "C" (очистка)
    public void onClear() {                                     // Объявляем публичный метод полной очистки калькулятора
        display.setText("0");                                   // Устанавливаем текст экрана в "0"
        num1 = 0;                                               // Сбрасываем первое число в 0
        operator = "";                                          // Сбрасываем оператор в пустую строку
        start = true;                                           // Устанавливаем флаг start в true, готовим калькулятор к новому вводу с нуля
    }                                                           // Закрываем метод onClear
}                                                               // Закрываем класс HelloController